CREATE TABLE IF NOT EXISTS profiles (user_id TEXT PRIMARY KEY, display_name TEXT NOT NULL DEFAULT 'Friend', daily_calorie_goal NUMERIC NOT NULL DEFAULT 2000, protein_goal NUMERIC NOT NULL DEFAULT 100, carbs_goal NUMERIC NOT NULL DEFAULT 250, fat_goal NUMERIC NOT NULL DEFAULT 65, water_goal_ml INTEGER NOT NULL DEFAULT 2500, weight_kg NUMERIC, goal_weight_kg NUMERIC, timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata', updated_at TIMESTAMPTZ NOT NULL DEFAULT now())